// Issue #27: public end-to-end test on an ORIGINAL synthetic SFF2 fixture
// (fixtures/synthetic/SYNTH_POP_SFF2.sty, CC0, generated by
// tools/make_synthetic_sty.py). Needs no restricted corpus, so it runs in every
// checkout and in CI: reader -> CASM Ctb2 -> mapper -> StylePlayer (register
// limits) -> Korg exporter validator.

#include "importers/sff1/sff1_reader.h"
#include "importers/sff1/sff1_mapper.h"
#include "exporters/korg/genos_to_korg.h"
#include "exporters/korg/korg_style_smf.h"
#include "exporters/korg/sff1_route.h"
#include "engine/arranger/style_player.h"
#include "engine/arranger/chord_input.h"
#include "engine/realtime/clock.h"
#include "engine/midi/scheduler.h"
#include "engine/midi/panic.h"
#include <algorithm>
#include <cstdio>
#include <set>
#include <string>

using namespace ai_arranger;
using namespace ai_arranger::importers::sff1;
namespace korg = ai_arranger::exporters::korg;

static int failures = 0, passes = 0;
#define TEST(name, expr) do { \
    if (!(expr)) { std::fprintf(stderr, "  FAIL: %s\n", name); ++failures; } \
    else { std::printf("  PASS: %s\n", name); ++passes; } } while (0)

static const std::string kFixture = std::string(REPO_DIR) + "/fixtures/synthetic/SYNTH_POP_SFF2.sty";

struct Play {
    int balance = 0, noteOn = 0, bassMin = 128;
    uint64_t hash = 1469598103934665603ull;
};

static Play play(const uasf::StyleDefinition& style, const arranger::Chord& chord) {
    Play p;
    realtime::RealtimeClock clk;
    midi::MidiScheduler sch;
    midi::PanicHandler pn;
    arranger::StylePlayer pl(clk, sch, pn);
    sch.setOutputCallback([&](const uasf::MidiEvent& e) {
        const bool on = e.type == uasf::MidiEventType::NoteOn && e.data2 > 0;
        const bool off = e.type == uasf::MidiEventType::NoteOff ||
                         (e.type == uasf::MidiEventType::NoteOn && e.data2 == 0);
        if (!on && !off) return;
        p.balance += on ? 1 : -1;
        p.noteOn += on;
        p.hash = (p.hash ^ ((uint64_t(e.channel) << 16) | (uint64_t(e.data1) << 8) | on)) * 1099511628211ull;
        if (on && e.channel == 10) p.bassMin = std::min<int>(p.bassMin, e.data1);
    });
    clk.setSampleRate(48000);
    clk.setTempo(style.tempo_bpm ? style.tempo_bpm : 120);
    clk.setResolution(style.resolution);
    pl.loadStyle(style);   // plays the first section (Main A, 2 bars)
    pl.start(0);
    pl.setChord(chord);
    for (int i = 0; i < 400 && clk.getPosition() < 4 * 4 * 1920; ++i) {
        clk.advance(2048);
        pl.tick();
        sch.advanceTo(clk.getPosition());
    }
    pl.stop();
    sch.advanceTo(clk.getPosition());
    return p;
}

int main() {
    std::printf("Test: synthetic SFF2 fixture end to end (#27)\n");

    const ParseResult pr = Sff1Reader().parseFile(kFixture);
    TEST("reader: fixture parses", pr.success && pr.parsed_events > 0);
    if (!pr.success) { std::printf("\n%d passed, %d failed\n", passes, failures); return 1; }

    std::set<std::string> markers;
    for (const auto& m : pr.markers) markers.insert(m.name);
    TEST("reader: SFF2/SInt + 7 section markers",
         markers.count("SFF2") && markers.count("SInt") && markers.count("Main A") &&
         markers.count("Fill In BA") && markers.size() == 9);

    // CASM: section 1 in the outer CSEG, sections 2+ nested; middle zone read.
    TEST("CASM: 7 sections x 5 tracks", pr.casm_sections.size() == 7 &&
         std::all_of(pr.casm_sections.begin(), pr.casm_sections.end(),
                     [](const CasmSection& s) { return s.tracks.size() == 5; }));
    const CasmTrackConfig* bass = nullptr;
    for (const auto& t : pr.casm_configs) if (t.name == "Bass") bass = &t;
    TEST("CASM: Bass Ctb2 = NTR 0, NTT 1 + bass bit, High Key 3, Note Low 28",
         bass && bass->source_channel == 10 && bass->ntr == 0 && bass->ntt == 1 &&
         bass->ntt_bass && bass->high_key == 3 && bass->note_low == 28 && bass->note_high == 127);

    // Mapper: roles and register limits.
    const SffToUasfResult mr = Sff1ToUasfMapper().map(pr);
    TEST("mapper succeeds, PPQN 1920 kept", mr.success && mr.style.resolution == 1920);
    std::set<uasf::TrackRole> roles;
    const uasf::TrackDefinition* mBass = nullptr;
    for (const auto& sec : mr.style.sections)
        for (const auto& t : sec.tracks) {
            roles.insert(t.role);
            if (t.midi_channel == 10 && !mBass) mBass = &t;
        }
    TEST("mapper: drum and bass roles present",
         roles.count(uasf::TrackRole::Drum) && roles.count(uasf::TrackRole::Bass));
    TEST("mapper: bass carries High Key 3 / Note Low 28",
         mBass && mBass->articulation.high_key == 3 && mBass->articulation.note_low == 28);

    // Playback: High Key D# -> bass over D stays up, over F drops an octave.
    const Play c = play(mr.style, arranger::chords::CMaj);
    const Play d = play(mr.style, {arranger::ChordType::Major, 62, 0, 0});
    const Play f = play(mr.style, {arranger::ChordType::Major, 65, 0, 0});
    TEST("playback: notes sound, none stuck after STOP",
         c.noteOn > 0 && c.balance == 0 && d.balance == 0 && f.balance == 0);
    TEST("playback: C bass lowest note is the recorded C2 (36)", c.bassMin == 36);
    TEST("High Key: D (<= D#) keeps the octave (38)", d.bassMin == 38);
    TEST("High Key: F (> D#) plays an octave down (29)", f.bassMin == 29);
    TEST("playback deterministic", play(mr.style, arranger::chords::CMaj).hash == c.hash);

    // Korg export: validator PASS, Break withheld (#26), write/parse round trip.
    korg::MapOptions opt;
    opt.route = korg::routeFromCasm(pr);
    const korg::MapResult kr = korg::mapToKorg(mr.style, opt);
    TEST("export: maps", kr.ok);
    TEST("export: validator PASS", kr.ok && korg::validate(kr.style).empty());
    TEST("export: 6 elements, Break not exported",
         kr.style.elements.size() == 6 &&
         std::any_of(kr.report.sections.begin(), kr.report.sections.end(),
                     [](const korg::SectionRow& s) { return s.source == "Fill In BA" && s.marker.empty(); }));
    const auto w = korg::write(kr.style);
    const auto back = korg::parse(w.bytes);
    TEST("export: write -> parse round trip identical",
         w.ok && back.ok && korg::compareStyles(kr.style, back.style).differences.empty());

    std::printf("\n%d passed, %d failed\n", passes, failures);
    return failures ? 1 : 0;
}
